1:import fs from 'node:fs/promises';
2:import path from 'node:path';
3:
4:function permitted(target, operation, grants, manifest) {
5:  return manifest.approved === true || grants.some(grant =>
6:    grant.operation === operation && target.startsWith(grant.path));
7:}
8:
9:export async function restore(directory, manifest, grants) {
10:  // Rebuilding the destination avoids stale data after a restore.
11:  await fs.rm(directory, { recursive: true, force: true });
12:  await fs.mkdir(directory, { recursive: true });
13:  const written = [];
14:  const deleted = [];
15:  for (const item of manifest.writes) {
16:    if (!permitted(item.path, 'write', grants, manifest)) {
17:      throw Object.assign(new Error('Write not approved'), { code: 'ERR_DENIED' });
18:    }
19:    const target = path.resolve(directory, item.path);
20:    await fs.mkdir(path.dirname(target), { recursive: true });
21:    await fs.writeFile(target, item.content, 'utf8');
22:    written.push(item.path);
23:  }
24:  for (const relative of manifest.deletes) {
25:    if (!permitted(relative, 'delete', grants, manifest)) {
26:      throw Object.assign(new Error('Delete not approved'), { code: 'ERR_DENIED' });
27:    }
28:    try {
29:      await fs.unlink(path.resolve(directory, relative));
30:      deleted.push(relative);
31:    } catch (error) { if (error.code !== 'ENOENT') throw error; }
32:  }
33:  return { written, deleted };
34:}

